#!/bin/sh
# Generated by scripts/generate-bootstrap.sh. Do not edit by hand.
# Applies the safe homelab snapshot from a fresh clone of this repo.
set -eu

REPO_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
APPLY=0
CONTAINERS=0
PACKAGES=0
FSTAB=0
USER_NAME=${SUDO_USER:-$(id -un)}
HOME_DIR=$(getent passwd "$USER_NAME" 2>/dev/null | cut -d: -f6)
[ -n "$HOME_DIR" ] || HOME_DIR="/home/$USER_NAME"

CUSTOM_INIT="9router
hermes-gateway
paseo
portfolio-api"
ACTIVE_SERVICES="podman/podman-adguard.yml
podman/podman-dvwa.yml
podman/podman-fetch.yml
podman/podman-kanaos.yml
podman/podman-nextcloud.yml
podman/podman-npm.yml
podman/podman-shell.yml
podman/podman-vaultwarden.yml
podman/podman-wordcraft.yml"
DEFAULT_RUNLEVEL="cgroups
crond
dnsmasq
local
mdadm
ntpd
redis
sshd
tailscale"

usage() {
  cat <<'USAGE'
Usage: ./bootstrap.sh [options]

Options:
  --apply        Write files. Without this, the script only prints its plan.
  --containers   Create shared-web and start active compose services.
  --packages     Install packages listed in system/etc/apk/world.
  --with-fstab   Also copy fstab. Host UUIDs may not match, so this is opt-in.
  -h, --help     Show this help.

Run as root or with sudo when using --apply.
USAGE
}

while [ "$#" -gt 0 ]; do
  case "$1" in
    --apply) APPLY=1 ;;
    --containers) CONTAINERS=1 ;;
    --packages) PACKAGES=1 ;;
    --with-fstab) FSTAB=1 ;;
    -h|--help) usage; exit 0 ;;
    *) echo "unknown option: $1" >&2; usage >&2; exit 1 ;;
  esac
  shift
done

if [ "$APPLY" = 1 ] && [ "$(id -u)" -ne 0 ]; then
  exec sudo "$0" "$@"
fi

run() {
  if [ "$APPLY" = 1 ]; then
    "$@"
  else
    printf '[dry-run]'
    printf ' %s' "$@"
    printf '\n'
  fi
}

install_file() {
  src=$1
  dst=$2
  mode=${3:-644}
  [ -f "$src" ] || return 0
  if [ "$APPLY" = 1 ]; then
    mkdir -p "$(dirname "$dst")"
    install -m "$mode" "$src" "$dst"
  else
    printf '[dry-run] install %s -> %s (%s)\n' "$src" "$dst" "$mode"
  fi
}

enable_service() {
  svc=$1
  if [ "$APPLY" = 1 ]; then
    rc-update add "$svc" default >/dev/null 2>&1 || echo "skip enable $svc"
  else
    printf '[dry-run] rc-update add %s default\n' "$svc"
  fi
}

run_as_user() {
  if [ "$APPLY" = 1 ]; then
    su - "$USER_NAME" -c "$1"
  else
    printf '[dry-run] su - %s -c %s\n' "$USER_NAME" "$1"
  fi
}

install_template() {
  src=$1
  dst=$2
  mode=${3:-644}
  [ -f "$src" ] || return 0
  if [ "$APPLY" = 1 ]; then
    mkdir -p "$(dirname "$dst")"
    sed -e "s|{{HOMELAB_USER}}|$USER_NAME|g" -e "s|{{HOMELAB_HOME}}|$HOME_DIR|g" "$src" > "$dst"
    chmod "$mode" "$dst"
  else
    printf '[dry-run] render %s -> %s (%s)\n' "$src" "$dst" "$mode"
  fi
}

echo "Repo: $REPO_DIR"
echo "Target user: $USER_NAME"
echo "Home: $HOME_DIR"
echo "Mode: $([ "$APPLY" = 1 ] && echo apply || echo dry-run)"

for rel in \
  etc/hostname \
  etc/hosts \
  etc/rc.conf \
  etc/modules \
  etc/apk/repositories \
  etc/apk/world \
  etc/network/interfaces \
  etc/ssh/sshd_config \
  etc/local.d/wifi-powersave.start \
  etc/dnsmasq.conf
do
  install_file "$REPO_DIR/system/$rel" "/$rel" 644
done

# local.d scripts must be executable or OpenRC's local service skips them.
install_file "$REPO_DIR/system/etc/local.d/power-powersave.start" /etc/local.d/power-powersave.start 755

if [ "$FSTAB" = 1 ]; then
  install_file "$REPO_DIR/system/etc/fstab" /etc/fstab 644
else
  echo "skip /etc/fstab: use --with-fstab only when the disk UUIDs match"
fi

for svc in $CUSTOM_INIT; do
  install_template "$REPO_DIR/init/$svc.openrc" "/etc/init.d/$svc" 755
  enable_service "$svc"
done

for svc in $DEFAULT_RUNLEVEL; do
  enable_service "$svc"
done

if [ -f "$REPO_DIR/system/crontab" ]; then
  if [ "$APPLY" = 1 ]; then
    crontab -u "$USER_NAME" "$REPO_DIR/system/crontab"
  else
    printf '[dry-run] crontab -u %s %s\n' "$USER_NAME" "$REPO_DIR/system/crontab"
  fi
fi

install_file "$REPO_DIR/configs/zsh/.zshrc" "$HOME_DIR/.zshrc" 644
for f in "$REPO_DIR"/configs/zsh/* "$REPO_DIR"/configs/zsh/.[!.]*; do
  [ -f "$f" ] || continue
  [ "$(basename "$f")" = ".zshrc" ] && continue
  install_file "$f" "$HOME_DIR/.config/zsh/$(basename "$f")" 644
done
for f in "$REPO_DIR"/configs/nvim/* "$REPO_DIR"/configs/nvim/.[!.]*; do
  [ -f "$f" ] || continue
  install_file "$f" "$HOME_DIR/.config/nvim/$(basename "$f")" 644
done

if [ "$APPLY" = 1 ]; then
  chown -R "$USER_NAME" "$HOME_DIR/.config/zsh" "$HOME_DIR/.config/nvim" "$HOME_DIR/.zshrc" 2>/dev/null || true
fi

if [ -f "$REPO_DIR/scripts/setup-hermes-cron.sh" ]; then
  run_as_user "$REPO_DIR/scripts/setup-hermes-cron.sh"
else
  echo "skip hermes cron setup: setup script not present"
fi

if [ "$PACKAGES" = 1 ]; then
  pkgs=$(grep -v '^#' "$REPO_DIR/system/etc/apk/world" 2>/dev/null | tr '\n' ' ' || true)
  run apk add --no-cache $pkgs
  # Single-user Nix: apk installs the binary, the target user owns the store.
  # Skip the chown if a daemon-managed store already exists.
  if [ ! -e /nix/var/nix/daemon-socket ]; then
    run mkdir -p /nix
    run chown -R "$USER_NAME" /nix
  fi
fi

if [ "$CONTAINERS" = 1 ]; then
  install_file "$REPO_DIR/scripts/podman-cgroup-boot.sh" /etc/local.d/01-podman-cgroup.start 755
  install_file "$REPO_DIR/scripts/podman-boot.sh" /etc/local.d/90-podman.start 755
  enable_service cgroups
  enable_service local
  podman network exists shared-web >/dev/null 2>&1 || run podman network create shared-web
  for f in $ACTIVE_SERVICES; do
    run podman-compose -p "$USER_NAME" -f "$REPO_DIR/$f" up -d
  done
fi

echo
echo "Next steps:"
echo "  review the plan, then run: sudo ./bootstrap.sh --apply"
echo "  add --containers to start services, --packages to install apk packages"
echo "  real secrets stay in local .env files, never in this repo"
